namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.Add(new(NextId(), "Welcome to the app!", DateTime.UtcNow.AddMinutes(-10)));
        _notifications.Add(new(NextId(), "Your profile was updated.", DateTime.UtcNow.AddMinutes(-5)));
        _notifications.Add(new(NextId(), "New feature available: dark mode.", DateTime.UtcNow.AddMinutes(-2)));
    }

    /// <summary>Returns all notifications currently available.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock) return _notifications.ToList();
    }

    /// <summary>Returns only notifications with an Id greater than <paramref name="sinceId"/>.</summary>
    public List<Notification> GetSince(int sinceId)
    {
        lock (_lock) return _notifications.Where(n => n.Id > sinceId).ToList();
    }

    /// <summary>Simulates an external system producing a new notification.</summary>
    public void SimulateIncoming()
    {
        var messages = new[]
        {
            "Server health check passed.",
            "Disk usage above 80%.",
            "New user signed up.",
            "Deployment completed successfully.",
            "Scheduled backup finished.",
            "Payment received.",
            "Security scan completed."
        };

        lock (_lock)
        {
            var msg = messages[Random.Shared.Next(messages.Length)];
            _notifications.Add(new(NextId(), msg, DateTime.UtcNow));
        }
    }

    private int NextId() => _nextId++;
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationService
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@_notifications.Count</span></h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private int _latestId;

    // Runs during both SSR and interactive — loads initial data so it
    // appears in the first server-rendered HTML.
    protected override void OnInitialized()
    {
        _notifications = NotificationService.GetAll();
        _latestId = _notifications.Count > 0
            ? _notifications.Max(n => n.Id)
            : 0;
    }

    // Only fires once the circuit is live (interactive), never during SSR.
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct)
                       .ConfigureAwait(false);

            // Simulate an external system occasionally adding a notification.
            NotificationService.SimulateIncoming();

            var newer = NotificationService.GetSince(_latestId);
            if (newer.Count > 0)
            {
                _notifications.AddRange(newer);
                _latestId = newer.Max(n => n.Id);

                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

