+@page "/notifications"
+@rendermode InteractiveServer
+@using NotificationsApp.Services
+@inject NotificationService NotificationService
+@implements IDisposable
+
+<PageTitle>Notifications</PageTitle>
+
+<h1>Notifications <span class="badge bg-primary">@_notifications.Count</span></h1>
+
+@if (_notifications.Count == 0)
+{
+    <p><em>No notifications.</em></p>
+}
+else
+{
+    <ul class="list-group">
+        @foreach (var n in _notifications)
+        {
+            <li class="list-group-item d-flex justify-content-between align-items-start">
+                <span>@n.Message</span>
+                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
+            </li>
+        }
+    </ul>
+}
+
+@code {
+    private List<Notification> _notifications = new();
+    private CancellationTokenSource? _cts;
+    private int _latestId;
+
+    // Runs during both SSR and interactive — loads initial data so it
+    // appears in the first server-rendered HTML.
+    protected override void OnInitialized()
+    {
+        _notifications = NotificationService.GetAll();
+        _latestId = _notifications.Count > 0
+            ? _notifications.Max(n => n.Id)
+            : 0;
+    }
+
+    // Only fires once the circuit is live (interactive), never during SSR.
+    protected override void OnAfterRender(bool firstRender)
+    {
+        if (firstRender)
+        {
+            _cts = new CancellationTokenSource();
+            _ = PollForNotificationsAsync(_cts.Token);
+        }
+    }
+
+    private async Task PollForNotificationsAsync(CancellationToken ct)
+    {
+        while (!ct.IsCancellationRequested)
+        {
+            await Task.Delay(TimeSpan.FromSeconds(5), ct)
+                       .ConfigureAwait(false);
+
+            // Simulate an external system occasionally adding a notification.
+            NotificationService.SimulateIncoming();
+
+            var newer = NotificationService.GetSince(_latestId);
+            if (newer.Count > 0)
+            {
+                _notifications.AddRange(newer);
+                _latestId = newer.Max(n => n.Id);
+
+                await InvokeAsync(StateHasChanged);
+            }
+        }
+    }
+
+    public void Dispose()
+    {
+        _cts?.Cancel();
+        _cts?.Dispose();
+    }
+}
